class DynamicMLP(nn.Module):

    def __init__(self, input_dim, output_dim):

        super().__init__()

        self.add_module(
            "fc1",
            nn.Linear(input_dim, 32)
        )

        self.add_module(
            "relu1",
            nn.ReLU()
        )

        self.add_module(
            "fc2",
            nn.Linear(32, output_dim)
        )

    def forward(self, x):

        x = self.fc1(x)
        x = self.relu1(x)
        x = self.fc2(x)

        return x

